						grid[i][k] = true
					}
					found = true
					break
				} 
			}
		}

		if !found {
			break
		}

		ret = !ret
	}

	if !ret {
		fmt.Println("Malvika")
	} else {
		fmt.Println("Akshat")
	}
}
